import type { FoundryChatMessage, WfrpActor, WfrpTest } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { isWfrpActor } from "./documents";
import {
  clearPendingCorruption,
  getPendingCorruption,
  markPendingCorruptionTest,
} from "./pending-corruption";
import { reportMutationError } from "./messages";
import { runFailedCorruptionCheck } from "./workflow";

const CORRUPTION_FLOW_FLAG = "mutantsHandbookCorruptionFlow";
const activeContinuations = new Set<string>();
const activeRerollTransfers = new Map<string, Promise<boolean>>();

interface CorruptionFlowFlag {
  actorUuid: string;
  status: "complete" | "pending";
  version: 1;
}

function readFlowFlag(message: FoundryChatMessage): CorruptionFlowFlag | undefined {
  const value = message.flags?.[MODULE_ID]?.[CORRUPTION_FLOW_FLAG];
  if (typeof value !== "object" || value === null) return undefined;
  const flow = value as Partial<CorruptionFlowFlag>;
  if (
    typeof flow.actorUuid !== "string" ||
    (flow.status !== "complete" && flow.status !== "pending") ||
    flow.version !== 1
  ) {
    return undefined;
  }
  return flow as CorruptionFlowFlag;
}

async function setFlowFlag(
  message: FoundryChatMessage,
  flag: CorruptionFlowFlag | null,
): Promise<void> {
  if (typeof message.setFlag !== "function") {
    throw new Error("Foundry cannot store the Mutant's Handbook chat-card state.");
  }
  await message.setFlag(MODULE_ID, CORRUPTION_FLOW_FLAG, flag);
}

export async function prepareCorruptionTestCard(actor: WfrpActor, test: WfrpTest): Promise<void> {
  const messageId = test.context.messageId;
  const message = messageId ? game?.messages.get(messageId) : undefined;
  if (!messageId || !message) {
    throw new Error("The Endurance Test did not create a chat message to continue from.");
  }

  const failed = message.system.test?.failed ?? test.failed;
  await setFlowFlag(message, {
    actorUuid: actor.uuid,
    status: failed ? "pending" : "complete",
    version: 1,
  });
  if (!failed) return;

  try {
    await markPendingCorruptionTest(actor, messageId);
  } catch (error) {
    await setFlowFlag(message, null);
    throw error;
  }
}

export async function continueCorruptionFlow(message: FoundryChatMessage): Promise<boolean> {
  const flow = readFlowFlag(message);
  const messageId = message.id;
  if (!flow || flow.status !== "pending" || !messageId || activeContinuations.has(messageId)) {
    return false;
  }

  activeContinuations.add(messageId);
  try {
    const actor = await fromUuid(flow.actorUuid);
    if (!isWfrpActor(actor)) {
      throw new Error(`${flow.actorUuid} no longer resolves to a WFRP4e character Actor.`);
    }
    const pending = getPendingCorruption(actor);
    if (pending?.kind !== "test" || pending.messageId !== messageId) {
      throw new Error(`${actor.name} is no longer waiting on this Corruption Test.`);
    }
    const test = message.system.test;
    if (!test) {
      throw new Error("The Corruption Test chat message no longer contains its WFRP Test data.");
    }

    if (test.failed) {
      const continued = await runFailedCorruptionCheck(actor);
      if (!continued) return false;
      const current = getPendingCorruption(actor);
      if (current?.kind === "test" && current.messageId === messageId) {
        await clearPendingCorruption(actor);
      }
    } else {
      await clearPendingCorruption(actor);
    }

    await setFlowFlag(message, { ...flow, status: "complete" });
    return true;
  } finally {
    activeContinuations.delete(messageId);
  }
}

async function transferCorruptionFlowToRerollOnce(message: FoundryChatMessage): Promise<boolean> {
  const previousMessageId = message.system.test?.context.previousMessage;
  if (!previousMessageId || !message.id) return false;

  const previousMessage = game?.messages.get(previousMessageId);
  const previousFlow = previousMessage ? readFlowFlag(previousMessage) : undefined;
  if (!previousMessage || !previousFlow || previousFlow.status !== "pending") return false;

  const actor = await fromUuid(previousFlow.actorUuid);
  if (!isWfrpActor(actor)) {
    throw new Error(`${previousFlow.actorUuid} no longer resolves to a WFRP4e character Actor.`);
  }

  const failed = message.system.test?.failed;
  if (typeof failed !== "boolean") return false;
  await setFlowFlag(message, {
    actorUuid: previousFlow.actorUuid,
    status: failed ? "pending" : "complete",
    version: 1,
  });

  const pending = getPendingCorruption(actor);
  if (pending?.kind === "test" && pending.messageId === previousMessageId) {
    if (failed) await markPendingCorruptionTest(actor, message.id);
    else await clearPendingCorruption(actor);
  }

  if (typeof previousMessage.delete === "function") await previousMessage.delete();
  else await setFlowFlag(previousMessage, null);
  return true;
}

export async function transferCorruptionFlowToReroll(
  message: FoundryChatMessage,
): Promise<boolean> {
  const messageId = message.id;
  if (!messageId) return false;
  const active = activeRerollTransfers.get(messageId);
  if (active) return active;

  const transfer = transferCorruptionFlowToRerollOnce(message).finally(() => {
    activeRerollTransfers.delete(messageId);
  });
  activeRerollTransfers.set(messageId, transfer);
  return transfer;
}

function canContinue(message: FoundryChatMessage): boolean {
  return game?.user.isGM === true || message.isAuthor === true;
}

function addSuccessfulResult(message: FoundryChatMessage, html: HTMLElement): boolean {
  const flow = readFlowFlag(message);
  if (!flow || message.system.test?.failed !== false) return false;

  if (!html.querySelector(`[data-ratter-corruption-result="success"]`)) {
    const result = document.createElement("p");
    result.dataset["ratterCorruptionResult"] = "success";
    result.textContent = game!.i18n.localize("FVTT_WFRP_RATTER.Mutations.CorruptionHeld");
    const content = html.querySelector<HTMLElement>(".message-content") ?? html;
    content.append(result);
  }

  if (flow.status === "pending") {
    void continueCorruptionFlow(message).catch(reportMutationError);
  }
  return true;
}

function addContinueButton(message: FoundryChatMessage, html: HTMLElement): void {
  const flow = readFlowFlag(message);
  if (addSuccessfulResult(message, html)) return;
  if (
    !flow ||
    flow.status !== "pending" ||
    message.system.test?.failed !== true ||
    !canContinue(message)
  ) {
    return;
  }
  if (html.querySelector(`[data-ratter-action="continue-corruption"]`)) return;

  const button = document.createElement("button");
  button.type = "button";
  button.classList.add("chat-button");
  button.dataset["ratterAction"] = "continue-corruption";
  button.innerHTML = `<i class="fa-solid fa-forward"></i> ${game!.i18n.localize(
    "FVTT_WFRP_RATTER.Mutations.ContinueCorruption",
  )}`;
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      const completed = await continueCorruptionFlow(message);
      if (!completed) button.disabled = false;
    } catch (error) {
      button.disabled = false;
      reportMutationError(error);
    }
  });

  const content = html.querySelector<HTMLElement>(".message-content") ?? html;
  content.append(button);
}

export function registerCorruptionChatHooks(): void {
  Hooks.on("createChatMessage", (message) => {
    void transferCorruptionFlowToReroll(message as FoundryChatMessage).catch(reportMutationError);
  });

  Hooks.on("renderChatMessageHTML", (message, html) => {
    if (typeof html !== "object" || html === null || !(html instanceof HTMLElement)) return;
    const chatMessage = message as FoundryChatMessage;
    addContinueButton(chatMessage, html);
    if (!readFlowFlag(chatMessage) && chatMessage.system.test?.context.previousMessage) {
      void transferCorruptionFlowToReroll(chatMessage)
        .then(() => addContinueButton(chatMessage, html))
        .catch(reportMutationError);
    }
  });
}
