import {
  getMutationAction,
  type MutationActionDefinition,
} from "../../../../functions/mutants-handbook/actions";
import { annotateMutationActionTest, mutationActionChatCard } from "./card";
import {
  actionContext,
  actionIdFromItem,
  isRecord,
  mutationActionActor,
  mutationActionItem,
  mutationActionTest,
} from "./documents";
import { mutationActionAvailable, mutationActionDifficulty, recordActionUse } from "./usage";
import type { MutationActionActor, MutationActionItem, MutationActionTest } from "./types";

export { applyMutationActionOutcome, messageHasMutationActionOutcome } from "./outcomes";

const dynamicDamageResults = new WeakSet<object>();

function actionDocuments(
  actorValue: unknown,
  itemValue: unknown,
  actionId: string,
):
  | { action: MutationActionDefinition; actor: MutationActionActor; item: MutationActionItem }
  | undefined {
  const action = getMutationAction(actionId);
  const actor = mutationActionActor(actorValue);
  const item = mutationActionItem(itemValue);
  if (!action || !actor || !item) return undefined;
  const flaggedId = actionIdFromItem(item);
  if (flaggedId !== undefined && flaggedId !== actionId) return undefined;
  return { action, actor, item };
}

function warnUnavailable(action: MutationActionDefinition, actor: MutationActionActor): void {
  const currentUi = Reflect.get(globalThis, "ui") as
    | { notifications?: { warn?: (message: string) => void } }
    | undefined;
  currentUi?.notifications?.warn?.(
    `${actor.name ?? "This Actor"} cannot use ${action.name}: its use limit or Advantage cost is not available.`,
  );
}

function prepareDynamicDamage(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  test: MutationActionTest,
): void {
  const multiplier = action.test?.bonusMultiplier ?? 1;
  const characteristic = action.test?.bonusCharacteristic;
  if (multiplier <= 1 || !characteristic) return;
  const context = actionContext(test);
  const marker = `mutationActionDamage:${action.id}`;
  if (typeof context[marker] === "number") return;
  const bonus = Number(actor.system?.characteristics?.[characteristic]?.bonus);
  if (!Number.isFinite(bonus)) return;
  const extra = bonus * (multiplier - 1);
  test.preData ??= {};
  const existing = Number(test.preData.additionalDamage) || 0;
  test.preData.additionalDamage = existing + extra;
  context[marker] = extra;
}

function applyDynamicDamageResult(
  action: MutationActionDefinition,
  test: MutationActionTest,
): void {
  const result = test.result;
  if (!result || dynamicDamageResults.has(result)) return;
  const extra = Number(actionContext(test)[`mutationActionDamage:${action.id}`]);
  const damage = Number(result.damage);
  if (!Number.isFinite(extra) || extra === 0 || !Number.isFinite(damage)) return;
  result.damage = damage + extra;
  result.breakdown?.damage?.other?.push({ label: action.name, value: extra });
  dynamicDamageResults.add(result);
}

export function prepareMutationActionDialog(
  actorValue: unknown,
  itemValue: unknown,
  actionId: string,
  argsValue: unknown,
): void {
  const documents = actionDocuments(actorValue, itemValue, actionId);
  if (!documents || !isRecord(argsValue)) return;
  const { action, actor, item } = documents;
  if (!mutationActionAvailable(action, actor, item)) {
    argsValue["abort"] = true;
    warnUnavailable(action, actor);
    return;
  }
  const fields = isRecord(argsValue["fields"]) ? argsValue["fields"] : {};
  argsValue["fields"] = fields;
  const difficulty = mutationActionDifficulty(action, item);
  if (difficulty) fields["difficulty"] = difficulty;
  const flags = isRecord(argsValue["flags"]) ? argsValue["flags"] : {};
  argsValue["flags"] = flags;
  flags["mutationActionId"] = action.id;
}

export async function recordMutationActionUse(
  actorValue: unknown,
  itemValue: unknown,
  actionId: string,
  testValue: unknown,
): Promise<boolean> {
  const documents = actionDocuments(actorValue, itemValue, actionId);
  const test = mutationActionTest(testValue);
  if (!documents || !test) return false;
  const { action, actor, item } = documents;
  const context = actionContext(test);
  context["mutationActionId"] = action.id;
  context["mutationActionItemUuid"] = item.uuid ?? item.id;
  test.preData ??= {};
  test.preData.options ??= {};
  test.preData.options["mutationActionActorUuid"] = actor.uuid ?? actor.id;
  test.preData.options["mutationActionId"] = action.id;
  test.preData.options["mutationActionItemUuid"] = item.uuid ?? item.id;
  test.preData.options["mutationActionUseId"] ??=
    globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
  const recorded = await recordActionUse(action, actor, item, test);
  if (!recorded) warnUnavailable(action, actor);
  else prepareDynamicDamage(action, actor, test);
  return recorded;
}

export async function resolveMutationActionTest(
  actorValue: unknown,
  itemValue: unknown,
  actionId: string,
  testValue: unknown,
): Promise<void> {
  const documents = actionDocuments(actorValue, itemValue, actionId);
  const test = mutationActionTest(testValue);
  if (!documents || !test) return;
  applyDynamicDamageResult(documents.action, test);
  annotateMutationActionTest(documents.action, documents.actor, documents.item, test);
}

function testContext(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
): Record<string, unknown> {
  const useId = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
  return {
    appendTitle: ` — ${action.mutationName}: ${action.name}`,
    fields: { difficulty: mutationActionDifficulty(action, item) ?? "challenging" },
    mutationActionId: action.id,
    mutationActionActorUuid: actor.uuid ?? actor.id,
    mutationActionItemUuid: item.uuid ?? item.id,
    mutationActionUseId: useId,
  };
}

async function setupActionTest(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
): Promise<MutationActionTest | undefined> {
  const context = testContext(action, actor, item);
  if (actor.setupTrait) return actor.setupTrait(item, context);
  if (action.test && "skill" in action.test && actor.setupSkill) {
    return actor.setupSkill(action.test.skill, context);
  }
  if (action.test && "characteristic" in action.test && actor.setupCharacteristic) {
    return actor.setupCharacteristic(action.test.characteristic, context);
  }
  return undefined;
}

async function postActionCard(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
): Promise<void> {
  const currentGame = Reflect.get(globalThis, "game") as
    | {
        wfrp4e?: { utility?: { chatDataSetup?: (content: string) => Record<string, unknown> } };
      }
    | undefined;
  const content = mutationActionChatCard(action);
  const data = currentGame?.wfrp4e?.utility?.chatDataSetup?.(content) ?? { content };
  data["flags"] = {
    ...(typeof data["flags"] === "object" && data["flags"] ? data["flags"] : {}),
    ["fvtt-wfrp-ratter"]: {
      mutationActionOutcome: {
        actionId: action.id,
        actorUuid: actor.uuid ?? actor.id,
        itemUuid: item.uuid ?? item.id,
      },
    },
  };
  const chatMessage = Reflect.get(globalThis, "ChatMessage") as
    | { create?: (message: Record<string, unknown>) => Promise<unknown> }
    | undefined;
  await chatMessage?.create?.(data);
}

export async function useMutationAction(
  actorValue: unknown,
  itemValue: unknown,
  actionId: string,
): Promise<void> {
  const documents = actionDocuments(actorValue, itemValue, actionId);
  if (!documents) return;
  const { action, actor, item } = documents;
  const test = action.test
    ? await setupActionTest(action, actor, item)
    : { context: testContext(action, actor, item) };
  if (!test) return;
  if (!(await recordMutationActionUse(actor, item, action.id, test))) return;
  if (action.test && test.roll) {
    await test.roll();
    return;
  }
  await postActionCard(action, actor, item);
}
