import type {
  MutationActionDefinition,
  MutationForm,
} from "../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../constants";
import {
  activeMutationItem,
  activeMutationLevels,
  isRecord,
  mutationAcquisition,
} from "./documents";
import { mutationEffectDuration, mutationNumber, mutationScriptData } from "./effect-helpers";
import {
  acquisitionFormChanges,
  acquisitionFormTestScript,
  createAcquisitionFormGrants,
  createFormItems,
} from "./form-items";
import type { MutationActionActor, MutationActionItem, MutationActionTest } from "./types";

const PHYSICAL = ["ws", "bs", "s", "t", "ag", "dex"] as const;
const FORM_BY_MUTATION_ID: Readonly<Record<string, MutationForm>> = {
  A7OLAWKXWUfh0UGU: "ethereal",
  XheCM6GZG8FhAoGp: "mirror-image",
  NDDLEunW5biRvTfy: "shapeshifter",
  JtmI1wOwKqWT4zVG: "skinwalker",
  q3sK3RsdsJxrifZP: "swarmform",
  jPlCrsK3hTgkHsTR: "warp-spasm",
  mNNavbJayRcsyeXJ: "werebeast",
};

function actorItems(actor: MutationActionActor): MutationActionItem[] {
  try {
    return actor.items ? [...actor.items] : [];
  } catch {
    return [];
  }
}

async function clearForm(actor: MutationActionActor, form: MutationForm): Promise<boolean> {
  const itemIds = actorItems(actor)
    .filter((item) => item.flags?.[MODULE_ID]?.["mutationForm"] === form)
    .flatMap((item) => (item.id ? [item.id] : []));
  const effectIds = [...(actor.effects ?? [])]
    .filter((effect) => effect.flags?.[MODULE_ID]?.["mutationForm"] === form)
    .flatMap((effect) => (effect.id ? [effect.id] : []));
  if (itemIds.length) await actor.deleteEmbeddedDocuments?.("Item", itemIds);
  if (effectIds.length) await actor.deleteEmbeddedDocuments?.("ActiveEffect", effectIds);
  return itemIds.length > 0 || effectIds.length > 0;
}

export async function clearMutationFormForMutation(
  actor: MutationActionActor,
  mutationId: string,
): Promise<void> {
  const form = FORM_BY_MUTATION_ID[mutationId];
  if (!form || activeMutationLevels(actor, mutationId) > 0) return;
  await clearForm(actor, form);
}

function effectData(
  action: MutationActionDefinition,
  form: MutationForm,
  description: string,
  rounds?: number,
  seconds?: number,
): Record<string, unknown> {
  const cleanup = `const ids = (this.actor.items ?? []).filter(item => item.flags?.["${MODULE_ID}"]?.mutationForm === "${form}").map(item => item.id);\nif (ids.length) await this.actor.deleteEmbeddedDocuments("Item", ids);`;
  return {
    changes: [],
    description,
    disabled: false,
    duration: mutationEffectDuration(rounds, seconds),
    flags: {
      [MODULE_ID]: { actionId: action.id, automationPhase: "mutation-phase-5", mutationForm: form },
      wfrp4e: {},
    },
    img: "icons/svg/mystery-man.svg",
    name: `${action.mutationName} — Active Form`,
    statuses: [],
    system: {
      scriptData: [mutationScriptData("Resolve Mutant's Handbook form", "deleteEffect", cleanup)],
      sourceData: {},
      transferData: {
        area: { aura: {} },
        avoidTest: { value: "none" },
        documentType: "Actor",
        equipTransfer: false,
        prompt: false,
        type: "document",
      },
      zone: {},
    },
    transfer: false,
    type: "base",
  };
}

function selected(acquisition: Record<string, unknown>, key: string): string {
  const selections = isRecord(acquisition["selections"]) ? acquisition["selections"] : {};
  const value = selections[key];
  return Array.isArray(value) ? String(value[0] ?? "") : String(value ?? "");
}

function swarmMovement(source: string): { move?: number; trait?: string } {
  return (
    {
      "amphibian": { move: 3, trait: "Swim 5" },
      "arthropod": { move: 3, trait: "Swim 4" },
      "bird-bat": { trait: "Flight 30" },
      "fish": { trait: "Swim 10" },
      "insect-spider": { move: 4, trait: "Flight 5" },
      "lizard-snake": { move: 5, trait: "Swim 4" },
      "mollusc": { move: 2, trait: "Swim 5" },
      "rodent-rabbit": { move: 5 },
    }[source] ?? {}
  );
}

export async function applyMutationForm(
  form: MutationForm,
  mode: "activate" | "revert",
  actor: MutationActionActor,
  action: MutationActionDefinition,
  test?: MutationActionTest,
  source?: MutationActionActor,
): Promise<void> {
  await clearForm(actor, form);
  if (mode === "revert") return;
  const item = activeMutationItem(actor, action.mutationId);
  const acquisition = mutationAcquisition(item);
  const sl = mutationNumber(test?.result?.SL);
  let effect = effectData(action, form, action.outcome);
  let items: Array<[string, "talent" | "trait"]> = [];
  if (form === "ethereal") {
    effect = effectData(
      action,
      form,
      action.outcome,
      Math.max(1, mutationNumber(actor.system?.characteristics?.["wp"]?.bonus) + sl),
    );
    items = [["Ethereal", "trait"]];
  } else if (form === "mirror-image") {
    const levels = Math.max(1, activeMutationLevels(actor, action.mutationId));
    const minutes =
      Math.max(1, mutationNumber(actor.system?.characteristics?.["wp"]?.value) + sl * 10) *
      2 ** (levels - 1);
    effect = effectData(action, form, action.outcome, undefined, minutes * 60);
  } else if (form === "shapeshifter") {
    const hours = Math.max(1, mutationNumber(actor.system?.characteristics?.["t"]?.bonus) + sl);
    effect = effectData(action, form, action.outcome, undefined, hours * 3600);
  } else if (form === "skinwalker" && source) {
    effect["changes"] = PHYSICAL.flatMap((key) => {
      const delta =
        mutationNumber(source.system?.characteristics?.[key]?.value) -
        mutationNumber(actor.system?.characteristics?.[key]?.value);
      return delta
        ? [
            {
              key: `system.characteristics.${key}.modifier`,
              mode: 2,
              priority: null,
              value: String(delta),
            },
          ]
        : [];
    });
    const sourceMove = mutationNumber(source.system?.details?.move?.value, Number.NaN);
    if (Number.isFinite(sourceMove)) {
      (effect["changes"] as Record<string, unknown>[]).push({
        key: "system.details.move.value",
        mode: 5,
        priority: null,
        value: String(sourceMove),
      });
    }
  } else if (form === "swarmform") {
    const movement = swarmMovement(selected(acquisition, "swarm-source"));
    effect["changes"] = [
      ...(movement.move === undefined
        ? []
        : [
            {
              key: "system.details.move.value",
              mode: 5,
              priority: null,
              value: String(movement.move),
            },
          ]),
      ...(selected(acquisition, "swarm-size")
        ? [
            {
              key: "system.details.size.value",
              mode: 5,
              priority: null,
              value: selected(acquisition, "swarm-size"),
            },
          ]
        : []),
    ];
    items = [
      ["Swarm", "trait"],
      ...(movement.trait ? [[movement.trait, "trait"] satisfies [string, "talent" | "trait"]] : []),
    ];
  } else if (form === "warp-spasm") {
    items = [
      ["Frenzy", "talent"],
      ["Berserk Charge", "talent"],
      ["Contortionist", "talent"],
      ["Painless", "trait"],
      ["Fear", "trait"],
    ];
    const system = effect["system"] as Record<string, unknown>;
    system["scriptData"] = [
      ...((system["scriptData"] as unknown[]) ?? []),
      mutationScriptData(
        "Resolve Mutant's Handbook form",
        "endCombat",
        "return this.effect.delete();",
      ),
      mutationScriptData(
        "Resolve Mutant's Handbook form",
        "deleteEffect",
        'await this.actor.addCondition("fatigued", 1);',
      ),
    ];
  } else if (form === "werebeast") {
    effect["changes"] = acquisitionFormChanges(acquisition);
    const testScript = acquisitionFormTestScript(acquisition);
    if (testScript) {
      const system = effect["system"] as Record<string, unknown>;
      system["scriptData"] = [...((system["scriptData"] as unknown[]) ?? []), testScript];
    }
    await createAcquisitionFormGrants(actor, form, acquisition);
  }
  await createFormItems(actor, form, items);
  await actor.createEmbeddedDocuments?.("ActiveEffect", [effect]);
}
